COLORS = {'Cobalt':'#2448F5','Lime':'#DDF45B','Cream':'#FFF8EA','Ink':'#17251C','White':'#FFFFFF'}

def rgb(h):
    return tuple(int(h[i:i+2],16) for i in (1,3,5))

def lum(h):
    values = [v/255 for v in rgb(h)]
    values = [v/12.92 if v <= .04045 else ((v+.055)/1.055)**2.4 for v in values]
    return sum(v*k for v,k in zip(values,(.2126,.7152,.0722)))

def contrast(a,b):
    l1,l2 = sorted((lum(COLORS[a]),lum(COLORS[b])))
    return (l2+.05)/(l1+.05)

