def logo(name='logo-stacked-primary.svg', cls='logo'):
    name = {'logo-stacked-primary.svg':'logo-stacked-cobalt.svg','logo-stacked-reversed.svg':'logo-stacked-cream.svg'}.get(name,name)
    return f'<img class="{cls}" src="../assets/logos/{name}" alt="Easy Food">'

def icon(name):
    return f'<img class="food-icon" src="../assets/icons/easy-{name}.svg" alt="{name}">'

def page(number, title, content, cls=''):
    return f'<section class="page {cls}"><div class="kicker"><span>EASY FOOD / BRAND GUIDELINES</span><span>{title}</span></div>{content}<footer class="footer"><span>Eat smart. Live easy.</span><span>Identity 01 · {number:02d} / 10</span></footer></section>'

